#include <iostream>
#include <string>
#include <regex>
#include <algorithm>
#include <sstream>

int getMaxWordLength(const std::string& s) {
    std::istringstream iss(s);
    std::string token;
    int maxLen = 0;
    while (std::getline(iss, token, '_')) {
        maxLen = std::max(maxLen, static_cast<int>(token.length()));
    }
    return maxLen;
}

std::string removeParentheses(const std::string& s) {
    if (s.length() >= 2) {
        return s.substr(1, s.length() - 2);
    }
    return s;
}

int main() {
    int n;
    std::cin >> n;
    std::cin.ignore(); // ignore the remaining newline after reading n
    std::string inputStr;
    std::getline(std::cin, inputStr);

    std::string patternStr = "\\([\\w_]*\\)";
    std::regex pattern(patternStr);
    std::sregex_iterator iter(inputStr.begin(), inputStr.end(), pattern);
    std::sregex_iterator end;

    int maxWordLen = 0;
    long long insideCount = 0;

    for (; iter != end; ++iter) {
        std::string inside = removeParentheses(iter->str());
        maxWordLen = std::max(maxWordLen, getMaxWordLength(inside));
        std::istringstream iss(inside);
        std::string s;
        while (std::getline(iss, s, '_')) {
            if (!s.empty()) {
                ++insideCount;
            }
        }
    }

    std::cout << maxWordLen << " " << insideCount << std::endl;
    return 0;
}
